import 'dart:io';
import 'dart:typed_data';
import 'package:flutter_test/flutter_test.dart';
import 'package:memora/ai/providers.dart';
import 'package:memora/core/grading.dart';
import 'package:memora/core/models.dart';
import 'package:memora/core/scheduler.dart';
import 'package:memora/storage/files.dart';
import 'package:memora/sync/sync_engine.dart';
class FailingTransport implements SyncTransport { @override Future<void> push(List<Map<String,dynamic>> records) => Future.error('offline'); }
void main(){final now=DateTime.utc(2025);test('mastery rises and correct streak delays review',(){var p=ConceptProgress(conceptId:'a');p=calculateMastery(progress:p,correct:true,now:now);expect(p.masteryScore,greaterThan(0));for(var i=0;i<4;i++)p=calculateMastery(progress:p,correct:true,now:now);expect(p.nextReviewAt,now.add(const Duration(days:14)));});test('wrong lowers mastery and returns quickly',(){final p=calculateMastery(progress:ConceptProgress(conceptId:'a',masteryScore:.8),correct:false,now:now);expect(p.masteryScore,lessThan(.8));expect(p.nextReviewAt!.difference(now),const Duration(minutes:15));});test('weak and repeatedly incorrect prioritized deterministically',(){final selected=selectNextConcept(concepts:[ConceptProgress(conceptId:'strong',masteryScore:.9),ConceptProgress(conceptId:'weak',masteryScore:.1,consecutiveIncorrect:2)],now:now);expect(selected!.conceptId,'weak');});test('strict analysis and question decoding',(){expect(PageAnalysis.fromJson({'printedText':'fact'}).printedText,'fact');expect(()=>PageAnalysis.fromJson({'printedText':4}),throwsFormatException);expect(()=>GeneratedQuestion.fromJson({'id':'q','conceptId':'c','prompt':'p','expectedAnswer':'a','explanation':'e','type':'multipleChoice','variantKey':'v','generationSeed':1,'choices':[]}),throwsFormatException);});test('provider registry and mock make no network request',()async{final mock=MockAIProvider();final registry=ProviderRegistry([mock]);expect(registry.get(AIProviderId.mock),same(mock));final analysis=await mock.analyzeDocument(AnalyzeDocumentInput(documentId:'d',bytes:Uint8List(1),mimeType:'image/png'));expect(analysis.pages.single.handwriting,isNotEmpty);});test('vendor configuration remains centralized',(){const models=ProviderModelConfig(documentAnalysis:'strong',classification:'fast',studyNotes:'fast',conceptExtraction:'fast',quizGeneration:'cheap');expect(GeminiProvider(apiKey:'x',models:models).models.quizGeneration,'cheap');expect(OpenAIProvider(apiKey:'x',models:models).id,AIProviderId.openAI);expect(AnthropicProvider(apiKey:'x',models:models).id,AIProviderId.anthropic);});test('duplicate prompts rejected and answers normalized',(){final g=DuplicateGuard();expect(g.accept('c','What is democracy?'),isTrue);expect(g.accept('c',' what  is DEMOCRACY? '),isFalse);expect(gradeAnswer(' Citizens   Elect Representatives. ','citizens elect representatives.'),isTrue);});test('confirmed correction wins re-analysis and conflict is visible',(){final local=_concept(now,userConfirmed:true);final incoming=_concept(now.add(const Duration(days:1)),statement:'AI replacement');expect(local.mergeAnalysis(incoming).statement,'fact');final engine=SyncEngine(FailingTransport());expect(engine.resolveConcept(local,incoming).syncState,SyncState.conflict);});test('local mutation survives sync failure and remains queued',()async{final result=await SyncEngine(FailingTransport()).synchronize([{'id':'attempt'}]);expect(result.state,SyncState.error);expect(result.pending,1);});test('secret keys excluded from sync payload',(){final payload=SyncEngine(FailingTransport()).settingsPayload(provider:'gemini',darkMode:true);expect(payload.containsKey('apiKey'),false);});test('concept serialization round trip',(){final c=_concept(now);expect(Concept.fromJson(c.toJson()).statement,c.statement);});test('file signatures not filenames determine accepted input',()async{final store=DocumentFileStore(Directory.systemTemp);expect(()=>store.preserveOriginal(documentId:'d',bytes:Uint8List.fromList([1,2,3])),throwsFormatException);});}
Concept _concept(DateTime now,{bool userConfirmed=false,String statement='fact'})=>Concept(id:'c',documentId:'d',subjectId:'s',unitId:'u',name:'name',statement:statement,explanation:'explanation',confidence:.9,sourceEvidence:[const SourceEvidence(documentId:'d',pageNumber:1,sourceType:SourceType.printedText,text:'fact',confidence:.9)],userConfirmed:userConfirmed,createdAt:now,updatedAt:now);
